		$(document).ready(function () {
			try {
				// Minimum characters required before performing a search/autocomplete
				var minPrefixLength = 3;
				var autoCompleteDebounceDelay = 500;
				var searchFieldSelector = "#searchField" + 'cd659bc7-654b-4dd5-8032-4b1d9f2f0df3';
				var checkboxSelector = "#ysnSearchOnlyDept" + 'cd659bc7-654b-4dd5-8032-4b1d9f2f0df3';
				var buttonSelector = ".widgetSearchButton" + 'cd659bc7-654b-4dd5-8032-4b1d9f2f0df3';
				var autoCompleteCache = {};
				var autoCompleteCacheKeys = [];
				var autoCompleteCacheLimit = 25;
				var currentAutoCompleteRequest = null;
				var currentAutoCompleteRequestKey = null;
				var autoCompleteDebounceTimer = null;
				var autoCompleteDebounceKey = null;
				var pendingAutoCompleteResponses = [];

				function normalizeAutoCompleteTerm(term) {
					return $.trim((term || "") + "").replace(/\s+/g, " ");
				}

				function shouldSearch(term) {
					return normalizeAutoCompleteTerm(term).length >= minPrefixLength;
				}

				function getAutoCompleteUrl() {
					return '/Search/AutoComplete' + ($(checkboxSelector).is(':checked') || false? '?departmentId=0' : '');
				}

				function getAutoCompleteCacheKey(requestUrl, term) {
					return requestUrl + "|" + term.toLowerCase();
				}

				function cacheAutoCompleteResult(cacheKey, data) {
					if (!Object.prototype.hasOwnProperty.call(autoCompleteCache, cacheKey)) {
						autoCompleteCacheKeys.push(cacheKey);
						if (autoCompleteCacheKeys.length > autoCompleteCacheLimit) {
							delete autoCompleteCache[autoCompleteCacheKeys.shift()];
						}
					}
					autoCompleteCache[cacheKey] = data;
				}

				function respondToPendingAutoComplete(data) {
					var responses = pendingAutoCompleteResponses;
					pendingAutoCompleteResponses = [];
					for (var i = 0; i < responses.length; i++) {
						responses[i](data);
					}
				}

				function cancelPendingAutoComplete() {
					clearTimeout(autoCompleteDebounceTimer);
					autoCompleteDebounceKey = null;
					if (currentAutoCompleteRequest != null) {
						currentAutoCompleteRequest.abort();
						currentAutoCompleteRequest = null;
					}
					currentAutoCompleteRequestKey = null;
					respondToPendingAutoComplete([]);
				}

				function createWidgetAutoCompleteSource(options) {
					return function (request, response) {
						var term = normalizeAutoCompleteTerm(request.term);
						if (!options.shouldSearch(term)) {
							response([]);
							return;
						}

						var requestUrl = options.url();
						var cacheKey = getAutoCompleteCacheKey(requestUrl, term);
						if (Object.prototype.hasOwnProperty.call(autoCompleteCache, cacheKey)) {
							response(autoCompleteCache[cacheKey]);
							if (options.success) {
								options.success(autoCompleteCache[cacheKey]);
							}
							return;
						}

						if (currentAutoCompleteRequestKey === cacheKey || autoCompleteDebounceKey === cacheKey) {
							pendingAutoCompleteResponses.push(response);
							return;
						}

						cancelPendingAutoComplete();
						autoCompleteDebounceKey = cacheKey;
						pendingAutoCompleteResponses.push(response);
						autoCompleteDebounceTimer = setTimeout(function () {
							autoCompleteDebounceKey = null;
							currentAutoCompleteRequestKey = cacheKey;
							currentAutoCompleteRequest = $.ajax({
								url: requestUrl,
								dataType: "json",
								timeout: options.timeout,
								data: {
									term: term,
								},
								success: function (data) {
									if (currentAutoCompleteRequestKey === cacheKey) {
										cacheAutoCompleteResult(cacheKey, data);
										respondToPendingAutoComplete(data);
										if (options.success) {
											options.success(data);
										}
									}
								},
								error: function (xmlhttprequest, textstatus, message) {
									if (textstatus === "abort") {
										return;
									}

									if (options.error) {
										options.error(xmlhttprequest, textstatus, message);
									}

									respondToPendingAutoComplete([]);
								},
								complete: function (xmlhttprequest) {
									if (currentAutoCompleteRequest === xmlhttprequest) {
										currentAutoCompleteRequest = null;
										currentAutoCompleteRequestKey = null;
									}
								}
							});
						}, options.delay);
					};
				}

				// click handler for search buttons
				$(buttonSelector).click(function (e) {
					e.preventDefault();
					var $btn = $(this);
					var $field = $btn.siblings(".widgetSearchBox");
					var term = $field.val() + "";
					if (!shouldSearch(term)) {
						// do nothing until user types enough characters
						$field.focus();
						return;
					}

					if ($(checkboxSelector).is(':checked') || false)
					{
						doWidgetSearch($.trim(term), Number(0));
					}
					else {
						doWidgetSearch($.trim(term), 0);
					}
				});

				// enter key handler for the search field
				$(searchFieldSelector).keypress(function (e) {
					var code = e.which || e.keyCode;
					if (code === 13) {
						e.preventDefault();
						var $this = $(this);
						var term = $this.val() + "";
						if (!shouldSearch(term)) {
							// do nothing until user types enough characters
							$this.focus();
							return false;
						}

						if ($(checkboxSelector).is(':checked') || false) {
							doWidgetSearch($.trim(term), Number(0));
						} else {
							doWidgetSearch($.trim(term), 0);
						}
						return false;
					}
					return true;
				});

				// autocomplete: set minLength and guard source
				if (true) {
					var $searchField = $(searchFieldSelector).autocomplete({
						minLength: minPrefixLength,
						source: createWidgetAutoCompleteSource({
							delay: autoCompleteDebounceDelay,
							timeout: 10000,
							shouldSearch: shouldSearch,
							url: getAutoCompleteUrl,
							success: function () {
								$('.autoCompleteError').remove();
							},
							error: function (xmlhttprequest, textstatus, message) {
								if (textstatus === "timeout") {
									if ($(searchFieldSelector).siblings('.autoCompleteError').length == 0)
										$('<span class="autoCompleteError"><p class="alert error">Search autocomplete is currently not responding. Please try again later.</p></span>').insertAfter($(searchFieldSelector));
								}
							}
						}),
						html: true,
						delay: 0,
						select: function (event, ui) {
							$(this).val(ui.item.value);
							$(this).next().click();
						}
					});

					$searchField.data("ui-autocomplete")._renderItem = function (ul, item) {
